pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address notOwner, uint256 newLimit) public {
        vm.assume(notOwner != address(this));
        vm.assume(notOwner != address(0));
        // Reference property: a non-owner call to AdjustBetAmounts must revert, leaving betLimit unchanged.
        // Bug: onlyOwner's require is removed, so a non-owner can change betLimit.
        uint256 beforeLimit = c.currentBetLimit();
        vm.prank(notOwner);
        bool ok = true;
        try c.AdjustBetAmounts(newLimit) { ok = true; } catch { ok = false; }
        uint256 afterLimit = c.currentBetLimit();
        // The invariant: after a non-owner attempt, betLimit must NOT change (revert OR same value).
        bool propertyHolds = (beforeLimit == afterLimit) && (!ok);
        assertTrue(propertyHolds);
    }
}

